Notes:
TC - O(nlogn)
SC - O(N)
// Pattern: Use Merge Sort; after both halves are sorted, count cross-half reverse pairs
// with two pointers BEFORE merging. Never reset the right pointer (`j`) because both
// halves are sorted, making the counting step O(n) and the overall algorithm O(n log n).

Sliding window approach;
TC - O(n) if no collision in uo_map;
SOLN:
class Solution {
public:
    int NoSubString(string& str, int k) {
        unordered_map<char, int> freq;
        int start = 0;
        freq[str[start]]++;
        int ans = 0;
        for(int i = 1; i < str.size(); i++){
            freq[str[i]]++;
            while(freq.size() > k){
                freq[str[start]]--;
                if(freq[str[start]] == 0){
                    freq.erase(str[start]);
                }
                start++;

            }
            if(freq.size() == k){
                ans += i - start;
            }
        }
        return ans;
    }
};

TC - O(log n)
SC - O(1)
Check was needed for if low = mid = high;
